'use strict';exports.isInteger=num=>typeof num==='number'?Number.isInteger(num):typeof num==='string'&&num.trim()!==''?Number.isInteger(Number(num)):false;exports.find=(node,type)=>node.nodes.find(node=>node.type===type);exports.exceedsLimit=(min,max,step=1,limit)=>limit===false?false:!exports.isInteger(min)||!exports.isInteger(max)?false:((Number(max)-Number(min))/Number(step))>=limit;exports.escapeNode=(block,n=0,type)=>{const node=block.nodes[n];if(!node)return;if((type&&node.type===type)||node.type==='open'||node.type==='close')if(node.escaped!==true){node.value='\\'+node.value;node.escaped=true}};exports.encloseBrace=node=>{if(node.type!=='brace')return false;if((node.commas>>0+node.ranges>>0)===0){node.invalid=true;return true}return false};exports.isInvalidBrace=block=>{if(block.type!=='brace')return false;if(block.invalid===true||block.dollar)return true;if((block.commas>>0+block.ranges>>0)===0){block.invalid=true;return true}if(block.open!==true||block.close!==true){block.invalid=true;return true}return false};exports.isOpenOrClose=node=>node.type==='open'||node.type==='close'?true:node.open===true||node.close===true;exports.reduce=nodes=>nodes.reduce((acc,node)=>{if(node.type==='text')acc.push(node.value);if(node.type==='range')node.type='text';return acc},[]);exports.flatten=(...args)=>{const result=[];const flat=arr=>{for(let i=0;i<arr.length;i++){const ele=arr[i];if(Array.isArray(ele)){flat(ele);continue}if(ele!==undefined)result.push(ele)}return result};flat(args);return result};